function sortVowels(s) {
  const isVowel = (ch) => 'aeiouAEIOU'.includes(ch);
  const vowels = [];

  for (const ch of s) {
    if (isVowel(ch)) {
      vowels.push(ch);
    }
  }
  vowels.sort();

  const result = [];
  let next = 0;
  for (const ch of s) {
    if (isVowel(ch)) {
      result.push(vowels[next]);
      next++;
    } else {
      result.push(ch);
    }
  }
  return result.join('');
}

