function sortVowels(s) {
  const chars = s.split('');
  const spots = [];
  for (let i = 0; i < chars.length; i++) if (/[aeiou]/i.test(chars[i])) spots.push(i);
  // Bubble sort the letters sitting at vowel positions by character code.
  for (let pass = 0; pass < spots.length; pass++)
    for (let k = 0; k + 1 < spots.length - pass; k++) {
      const a = spots[k], b = spots[k + 1];
      if (chars[a].charCodeAt(0) > chars[b].charCodeAt(0)) [chars[a], chars[b]] = [chars[b], chars[a]];
    }
  return chars.join('');
}

