function generate(rand, size) {
  const n = size === 'large' ? 10000 : 1 + Math.floor(rand() * 12);
  const vowelShare = [0, 0.3, 0.6, 1][Math.floor(rand() * 4)];
  const vowels = 'aeiouAEIOU';
  const consonants = 'bcdfghjklmnpqrstvwxyzBCDFGHJKLMNPQRSTVWXYZ';
  let s = '';
  for (let i = 0; i < n; i++) {
    const pool = rand() < vowelShare ? vowels : consonants;
    s += pool[Math.floor(rand() * pool.length)];
  }
  return [s];
}
